1	// Shared black-box harness: spawn `node server.mjs` and talk to it over HTTP or raw TCP.
2	import assert from 'node:assert/strict';
3	import { spawn } from 'node:child_process';
4	import http from 'node:http';
5	import net from 'node:net';
6	import fs from 'node:fs';
7	import os from 'node:os';
8	import path from 'node:path';
9	import { fileURLToPath } from 'node:url';
10	
11	export const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..', '..');
12	export const SERVER = path.join(ROOT, 'server.mjs');
13	export const JSON_TYPE = 'application/json; charset=utf-8';
14	export const JSON_HEADERS = Object.freeze({ 'content-type': 'application/json' });
15	export const LISTEN_RE = /^listening on http:\/\/127\.0\.0\.1:(\d+)\n$/;
16	const EXIT_TIMEOUT_MS = 10000;
17	
18	/** Fresh temp folder, removed after the test. */
19	export function makeTmp(t) {
20	  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'booking-h-'));
21	  t.after(() => fs.rmSync(dir, { recursive: true, force: true }));
22	  return dir;
23	}
24	
25	/**
26	 * Spawns the server. `env` entries override the defaults (PORT=0, DATA_FILE=<dir>/data.json);
27	 * an entry whose value is `undefined` removes that variable entirely.
28	 */
29	export function spawnServer(dir, { env = {}, cwd } = {}) {
30	  const merged = { ...process.env, PORT: '0', DATA_FILE: path.join(dir, 'data.json'), ...env };
31	  const fullEnv = Object.fromEntries(Object.entries(merged).filter(([, v]) => v !== undefined));
32	  return spawn(process.execPath, [SERVER], { env: fullEnv, cwd: cwd ?? dir });
33	}
34	
35	/**
36	 * Starts the server and resolves once it prints the listening line.
37	 * `out()` / `err()` return everything written to stdout / stderr so far.
38	 */
39	export function startServer(t, dir, opts = {}) {
40	  const child = spawnServer(dir, opts);
41	  t.after(() => child.kill('SIGKILL'));
42	  let stdout = '';
43	  let stderr = '';
44	  child.stdout.on('data', (d) => { stdout += d; });
45	  child.stderr.on('data', (d) => { stderr += d; });
46	  return new Promise((resolve, reject) => {
47	    const timer = setTimeout(() => {
48	      child.off('exit', onExit);
49	      child.kill('SIGKILL');
50	      reject(new Error(`no listening line within ${EXIT_TIMEOUT_MS} ms: ${stderr}`));
51	    }, EXIT_TIMEOUT_MS);
52	    const onData = () => {
53	      const m = LISTEN_RE.exec(stdout);
54	      if (!m) return;
55	      clearTimeout(timer);
56	      child.stdout.off('data', onData);
57	      child.off('exit', onExit);
58	      resolve({ port: Number(m[1]), child, out: () => stdout, err: () => stderr });
59	    };
60	    const onExit = (code) => {
61	      clearTimeout(timer);
62	      reject(new Error(`exited ${code} before listening: ${stderr}`));
63	    };
64	    child.stdout.on('data', onData);
65	    child.on('exit', onExit);
66	  });
67	}
68	
69	/** Kills a started server and resolves once its process is gone and its stdio is drained. */
70	export function stopServer(child) {
71	  if (child.exitCode !== null || child.signalCode !== null) return Promise.resolve();
72	  return new Promise((resolve) => {
73	    child.once('close', () => resolve());
74	    child.kill('SIGKILL');
75	  });
76	}
77	
78	/** Spawns the server in a fresh temp dir; returns { dir, port, child, out, err }. */
79	export async function boot(t, opts = {}) {
80	  const dir = makeTmp(t);
81	  const srv = await startServer(t, dir, opts);
82	  return { dir, ...srv };
83	}
84	
85	/**
86	 * Runs the server until it exits; resolves { code, stdout, stderr }.
87	 * When it is still running after the timeout it is killed and `code` is 'still running',
88	 * so the caller's own assertion (with its case label) reports the failure.
89	 */
90	export function runToExit(t, dir, opts = {}) {
91	  const child = spawnServer(dir, opts);
92	  t.after(() => child.kill('SIGKILL'));
93	  return new Promise((resolve) => {
94	    let stdout = '';
95	    let stderr = '';
96	    const timer = setTimeout(() => {
97	      child.removeAllListeners('close');
98	      child.kill('SIGKILL');
99	      resolve({ code: 'still running', stdout, stderr });
100	    }, EXIT_TIMEOUT_MS);
101	    child.stdout.on('data', (d) => { stdout += d; });
102	    child.stderr.on('data', (d) => { stderr += d; });
103	    // 'close' (not 'exit') fires only after stdout and stderr are fully read.
104	    child.on('close', (code) => {
105	      clearTimeout(timer);
106	      resolve({ code, stdout, stderr });
107	    });
108	  });
109	}
110	
111	/** HTTP request; resolves { status, headers, text, json } (json undefined when not JSON). */
112	export function request(port, method, reqPath, { headers = {}, body } = {}) {
113	  return new Promise((resolve, reject) => {
114	    const opts = { host: '127.0.0.1', port, method, path: reqPath, headers, agent: false };
115	    const req = http.request(opts, (res) => {
116	      const chunks = [];
117	      res.on('data', (c) => chunks.push(c));
118	      res.on('end', () => {
119	        const text = Buffer.concat(chunks).toString('utf8');
120	        let json;
121	        try { json = JSON.parse(text); } catch { json = undefined; }
122	        resolve({ status: res.statusCode, headers: res.headers, text, json });
123	      });
124	    });
125	    req.on('error', reject);
126	    req.end(body);
127	  });
128	}
129	
130	/** POST /api/bookings; objects are JSON-encoded, strings and Buffers are sent as is. */
131	export function post(port, obj, headers = JSON_HEADERS) {
132	  const body = typeof obj === 'string' || Buffer.isBuffer(obj) ? obj : JSON.stringify(obj);
133	  return request(port, 'POST', '/api/bookings', { headers, body });
134	}
135	
136	/**
137	 * Sends raw bytes over TCP and resolves the parsed status line, lower-cased headers and body text.
138	 * Use for request lines or headers that node:http would refuse to send. Send `Connection: close`:
139	 * the socket is not half-closed (node:http aborts a request whose client sent FIN), so the reply
140	 * ends when the server closes the connection.
141	 */
142	export function rawRequest(port, raw) {
143	  return new Promise((resolve, reject) => {
144	    const socket = net.connect(port, '127.0.0.1', () => socket.write(raw));
145	    const chunks = [];
146	    socket.on('data', (c) => chunks.push(c));
147	    socket.on('error', reject);
148	    socket.on('end', () => {
149	      const text = Buffer.concat(chunks).toString('utf8');
150	      const split = text.indexOf('\r\n\r\n');
151	      const head = split === -1 ? text : text.slice(0, split);
152	      const bodyText = split === -1 ? '' : text.slice(split + 4);
153	      const [statusLine, ...headerLines] = head.split('\r\n');
154	      const headers = Object.fromEntries(headerLines.map((l) => {
155	        const i = l.indexOf(':');
156	        return [l.slice(0, i).trim().toLowerCase(), l.slice(i + 1).trim()];
157	      }));
158	      let json;
159	      try { json = JSON.parse(bodyText); } catch { json = undefined; }
160	      resolve({ status: Number(statusLine.split(' ')[1]), headers, text: bodyText, json });
161	    });
162	  });
163	}
164	
165	/** A valid booking body; `over` replaces fields. */
166	export const valid = (over = {}) => ({
167	  room: 'Aurora', title: 'Standup', date: '2026-11-03', start: '10:00', end: '11:00', ...over,
168	});
169	
170	/** Asserts status, exact `{error}` body and the JSON content type; `label` names the case. */
171	export function assertError(res, status, message, label = '') {
172	  const at = label ? `${label}: ` : '';
173	  assert.equal(res.status, status, `${at}status`);
174	  assert.deepEqual(res.json, { error: message }, `${at}body`);
175	  assert.equal(res.headers['content-type'], JSON_TYPE, `${at}content-type`);
176	}
177	
178	/**
179	 * POST /api/bookings with `transfer-encoding: chunked` (no Content-Length), writing each Buffer of
180	 * `pieces` in turn and honouring back-pressure. Resolves { status, headers, text, json }.
181	 */
182	export function chunkedPost(port, pieces, headers = JSON_HEADERS) {
183	  return new Promise((resolve, reject) => {
184	    const req = http.request({
185	      host: '127.0.0.1', port, method: 'POST', path: '/api/bookings', agent: false,
186	      headers: { ...headers, 'transfer-encoding': 'chunked' },
187	    }, (res) => {
188	      const chunks = [];
189	      res.on('data', (c) => chunks.push(c));
190	      res.on('error', reject);
191	      res.on('end', () => {
192	        const text = Buffer.concat(chunks).toString('utf8');
193	        let json;
194	        try { json = JSON.parse(text); } catch { json = undefined; }
195	        resolve({ status: res.statusCode, headers: res.headers, text, json });
196	      });
197	    });
198	    req.on('error', reject);
199	    let next = 0;
200	    const pump = () => {
201	      while (next < pieces.length) {
202	        const piece = pieces[next];
203	        next += 1;
204	        if (!req.write(piece)) { req.once('drain', pump); return; }
205	      }
206	      req.end();
207	    };
208	    pump();
209	  });
210	}
211	
212	/** Resolves true when 127.0.0.1:<port> can be bound right now. */
213	export function portIsFree(port) {
214	  return new Promise((resolve) => {
215	    const probe = net.createServer();
216	    probe.once('error', () => resolve(false));
217	    probe.listen(port, '127.0.0.1', () => probe.close(() => resolve(true)));
218	  });
219	}
