1	import assert from 'node:assert/strict';
2	import { fileURLToPath } from 'node:url';
3	import { loadPage, makeReply, flush } from './fake-dom.mjs';
4	
5	/** Absolute filesystem path of the page script under test. */
6	export const APP = fileURLToPath(new URL('../../public/app.js', import.meta.url));
7	
8	/** Room names the fake /api/rooms endpoint answers with. */
9	export const ROOMS = ['Aurora', 'Borealis', 'Cosmos'];
10	
11	/** Build a booking record for room Aurora on 2026-11-03; `extra` overrides any field. */
12	export function booking(id, title, extra = {}) {
13	  return { id, room: 'Aurora', title, date: '2026-11-03', start: '09:00', end: '10:00', ...extra };
14	}
15	
16	/** Load the page, answer the rooms fetch and (unless answerList is false) the list fetch. */
17	export async function setup({ bookings = [booking(1, 'one')], answerList = true } = {}) {
18	  const page = loadPage(APP);
19	  assert.equal(page.calls[0].url, '/api/rooms');
20	  page.calls[0].reply(makeReply(200, { rooms: ROOMS }));
21	  if (answerList) page.calls[1].reply(makeReply(200, { bookings }));
22	  await flush();
23	  return page;
24	}
25	
26	/** Dispatch a submit event on the booking form and return the event. */
27	export function submit(els) {
28	  return els['booking-form'].dispatch('submit');
29	}
