1	// Black-box tests for the booking rules and the list endpoint of server.mjs.
2	import { test } from 'node:test';
3	import assert from 'node:assert/strict';
4	import {
5	  boot, post, request, rawRequest, valid, JSON_TYPE, assertError, chunkedPost,
6	} from './helpers/server-harness.mjs';
7	
8	const MISSING = Symbol('missing');
9	const MSG = {
10	  ct: 'content type must be application/json',
11	  big: 'body too large',
12	  obj: 'body must be a JSON object',
13	  room: 'room must be one of Aurora, Borealis, Cosmos',
14	  title: 'title must be 1 to 80 characters',
15	  date: 'date must be a valid YYYY-MM-DD date',
16	  start: 'start must be HH:MM',
17	  end: 'end must be HH:MM',
18	  order: 'end must be after start',
19	};
20	
21	/** valid() with `over` applied; MISSING removes the key. */
22	function body(over = {}) {
23	  const obj = valid(over);
24	  for (const [k, v] of Object.entries(over)) if (v === MISSING) delete obj[k];
25	  return obj;
26	}
27	
28	const CT = (value) => ({ 'content-type': value });
29	
30	/** Raw POST with a Buffer header line (or none) and an exact Content-Length. */
31	function rawPost(port, headerLine, payload) {
32	  const data = Buffer.isBuffer(payload) ? payload : Buffer.from(payload);
33	  const parts = [Buffer.from('POST /api/bookings HTTP/1.1\r\nHost: x\r\n')];
34	  if (headerLine) parts.push(Buffer.isBuffer(headerLine) ? headerLine : Buffer.from(headerLine), Buffer.from('\r\n'));
35	  parts.push(Buffer.from(`Content-Length: ${data.length}\r\nConnection: close\r\n\r\n`), data);
36	  return rawRequest(port, Buffer.concat(parts));
37	}
38	
39	/** Splits a Buffer into three consecutive pieces. */
40	function inThirds(payload) {
41	  const third = Math.floor(payload.length / 3);
42	  return [payload.subarray(0, third), payload.subarray(third, 2 * third), payload.subarray(2 * third)];
43	}
44	
45	/** A valid booking JSON text of exactly `bytes` bytes, optionally using 2-byte chars as padding. */
46	function sizedBody(bytes, multibyte) {
47	  const base = JSON.stringify({ ...valid(), pad: '' });
48	  const k = multibyte ? Math.floor((bytes - base.length) / 2) : 0;
49	  const text = JSON.stringify({ ...valid(), pad: 'é'.repeat(k) });
50	  return text + ' '.repeat(bytes - Buffer.byteLength(text));
51	}
52	
53	const hourSlot = (i) => ({ start: `${String(i).padStart(2, '0')}:00`, end: `${String(i).padStart(2, '0')}:30` });
54	
55	// ---------- rule 1 ----------
56	
57	test('rule 1: accepted media type spellings', async (t) => {
58	  const { port } = await boot(t);
59	  const accepted = ['Application/JSON ; charset=x', 'application/json;', 'APPLICATION/JSON'];
60	  for (const [i, ct] of accepted.entries()) {
61	    const res = await post(port, body(hourSlot(i)), CT(ct));
62	    assert.equal(res.status, 201, `accept ${JSON.stringify(ct)}`);
63	  }
64	  const tabbed = ['Content-Type:\tapplication/json\t;x', 'Content-Type: application/json\t;x',
65	    'Content-Type: application/json \t \t; charset=x'];
66	  for (const [i, line] of tabbed.entries()) {
67	    const raw = await rawPost(port, line, JSON.stringify(body(hourSlot(5 + i))));
68	    assert.equal(raw.status, 201, `accept tab padded raw header ${JSON.stringify(line)}`);
69	  }
70	});
71	
72	test('rule 1: rejected media types', async (t) => {
73	  const { port } = await boot(t);
74	  const rejected = ['application/json-patch', 'application/jsonx', 'text/json', 'application/json, text/plain',
75	    ';application/json', 'application/ json', 'application /json'];
76	  for (const ct of rejected) {
77	    assertError(await post(port, body(), CT(ct)), 415, MSG.ct, `reject ${JSON.stringify(ct)}`);
78	  }
79	  assertError(await post(port, body(), {}), 415, MSG.ct, 'missing header');
80	  const text = JSON.stringify(body());
81	  assertError(await rawPost(port, 'Content-Type: ', text), 415, MSG.ct, 'empty header value');
82	  const nbsp = Buffer.concat([Buffer.from('Content-Type:'), Buffer.from([0xa0]), Buffer.from('application/json')]);
83	  assertError(await rawPost(port, nbsp, text), 415, MSG.ct, 'latin1 nbsp padding');
84	});
85	
86	// ---------- rule 2 and rule order ----------
87	
88	test('rule 2: size limits by byte count', async (t) => {
89	  const { port } = await boot(t);
90	  const big = Buffer.alloc(20000, 0x61);
91	  assertError(await post(port, big, CT('text/plain')), 415, MSG.ct, 'bad type beats big body');
92	  assertError(await post(port, Buffer.alloc(10001, 0x7b)), 413, MSG.big, '10001 bytes invalid JSON');
93	  assertError(await post(port, sizedBody(10001, false)), 413, MSG.big, '10001 bytes valid booking');
94	  const ok = await post(port, sizedBody(10000, false));
95	  assert.equal(ok.status, 201, '10000 byte body accepted');
96	});
97	
98	test('rule 2: multi-byte characters count as bytes', async (t) => {
99	  const { port } = await boot(t);
100	  const over = JSON.stringify({ ...valid(), pad: 'é'.repeat(9990 - JSON.stringify({ ...valid(), pad: '' }).length) });
101	  assert.equal(over.length, 9990, 'test setup: character count');
102	  assert.ok(Buffer.byteLength(over) > 10000, 'test setup: byte count above limit');
103	  assertError(await post(port, over), 413, MSG.big, 'few chars, many bytes');
104	  const exact = sizedBody(10000, true);
105	  assert.equal(Buffer.byteLength(exact), 10000, 'test setup: exact bytes');
106	  assert.ok(exact.length < 10000, 'test setup: multi-byte chars present');
107	  assert.equal((await post(port, exact)).status, 201, 'exactly 10000 multi-byte bytes');
108	});
109	
110	test('rule 2: chunked uploads', async (t) => {
111	  const { port } = await boot(t);
112	  const tooBig = Buffer.from(sizedBody(10001, false));
113	  assert.equal(tooBig.length, 10001, 'test setup: chunked size');
114	  assertError(await chunkedPost(port, inThirds(tooBig)), 413, MSG.big, 'chunked 10001');
115	  const okRes = await chunkedPost(port, inThirds(Buffer.from(sizedBody(10000, false))));
116	  assert.equal(okRes.status, 201, 'chunked 10000 accepted');
117	});
118	
119	test('rule order: the first failing rule decides', async (t) => {
120	  const { port } = await boot(t);
121	  const cases = [
122	    ['room before title', { room: 'x', title: '' }, MSG.room],
123	    ['title before date', { title: '', date: 'x' }, MSG.title],
124	    ['date before start', { date: 'x', start: 'x' }, MSG.date],
125	    ['start before end', { start: 'x', end: 'x' }, MSG.start],
126	    ['end before order', { start: '10:00', end: 'x' }, MSG.end],
127	  ];
128	  for (const [label, over, message] of cases) {
129	    assertError(await post(port, body(over)), 400, message, label);
130	  }
131	  assertError(await post(port, '{not json, "room": "x"}'), 400, MSG.obj, 'invalid JSON beats room');
132	});
133	
134	test('rule order: end must be after start beats 409', async (t) => {
135	  const { port } = await boot(t);
136	  assert.equal((await post(port, body())).status, 201, 'seed');
137	  const equal = await post(port, body({ start: '10:30', end: '10:30' }));
138	  assertError(equal, 400, MSG.order, 'equal times inside an existing booking');
139	  const reversed = await post(port, body({ start: '10:30', end: '10:00' }));
140	  assertError(reversed, 400, MSG.order, 'reversed times inside an existing booking');
141	});
142	
143	// ---------- rule 3 ----------
144	
145	test('rule 3: bodies that are not JSON objects', async (t) => {
146	  const { port } = await boot(t);
147	  const bad = ['', ' ', 'null', '[]', '[{}]', '"x"', '0', 'false', '{', '{"room":"Aurora"} x'];
148	  for (const text of bad) {
149	    assertError(await post(port, text), 400, MSG.obj, `body ${JSON.stringify(text)}`);
150	  }
151	  const bom = Buffer.concat([Buffer.from([0xef, 0xbb, 0xbf]), Buffer.from(JSON.stringify(valid()))]);
152	  assertError(await post(port, bom), 400, MSG.obj, 'BOM prefix');
153	  assertError(await post(port, '{}'), 400, MSG.room, 'empty object');
154	});
155	
156	test('rule 3: whitespace and invalid UTF-8', async (t) => {
157	  const { port } = await boot(t);
158	  const ws = await post(port, `\n ${JSON.stringify(valid())} \n`);
159	  assert.equal(ws.status, 201, 'whitespace around object');
160	  const head = '{"room":"Aurora","title":"x';
161	  const tail = '","date":"2026-11-03","start":"12:00","end":"13:00"}';
162	  const titled = await post(port, Buffer.concat([Buffer.from(head), Buffer.from([0xff]), Buffer.from(tail)]));
163	  assert.equal(titled.status, 201, 'invalid byte in title status');
164	  assert.equal(titled.json.title, 'x\uFFFD', 'invalid byte in title becomes U+FFFD');
165	  const roomHead = Buffer.from('{"room":"Aurora');
166	  const roomTail = Buffer.from('","title":"x","date":"2026-11-03","start":"14:00","end":"15:00"}');
167	  const badRoom = await post(port, Buffer.concat([roomHead, Buffer.from([0xff]), roomTail]));
168	  assertError(badRoom, 400, MSG.room, 'invalid byte in room');
169	});
170	
171	// ---------- rule 4 ----------
172	
173	test('rule 4: room names', async (t) => {
174	  const { port } = await boot(t);
175	  const bad = ['aurora', 'AURORA', ' Aurora', 'Aurora ', 'Aurora\u0000', null, 1, ['Aurora'], MISSING, 'Nebula'];
176	  for (const room of bad) {
177	    const label = `room ${room === MISSING ? 'missing' : JSON.stringify(room)}`;
178	    assertError(await post(port, body({ room })), 400, MSG.room, label);
179	  }
180	  for (const room of ['Borealis', 'Cosmos']) {
181	    assert.equal((await post(port, body({ room }))).status, 201, `room ${room}`);
182	  }
183	  const proto = '{"__proto__":{"room":"Aurora"},"title":"t","date":"2026-11-03","start":"10:00","end":"11:00"}';
184	  assertError(await post(port, proto), 400, MSG.room, '__proto__ room');
185	});
186	
187	// ---------- rule 5 ----------
188	
189	test('rule 5: rejected titles', async (t) => {
190	  const { port } = await boot(t);
191	  const bad = ['', '   ', '\t\n', '\u3000\u00a0', null, 5, ['x'], MISSING, 'x'.repeat(81), ` ${'x'.repeat(81)} `,
192	    '😀'.repeat(41), `${'a'.repeat(79)}😀`];
193	  for (const [i, title] of bad.entries()) {
194	    const label = `title #${i} ${title === MISSING ? 'missing' : JSON.stringify(title)}`;
195	    assertError(await post(port, body({ title })), 400, MSG.title, label);
196	  }
197	});
198	
199	test('rule 5: accepted titles are stored trimmed', async (t) => {
200	  const { port } = await boot(t);
201	  const x80 = 'x'.repeat(80);
202	  const cases = [
203	    ['😀'.repeat(40), '😀'.repeat(40)], [` \t${x80}\t `, x80], ['\u3000hi\u00A0', 'hi'], ['\uFEFFhi\u2003', 'hi'],
204	    [' a  b ', 'a  b'], ['  hi', 'hi'], ['hi  ', 'hi'], ['\u200B', '\u200B'], ['<b>x</b>', '<b>x</b>'],
205	  ];
206	  const expected = [];
207	  for (const [i, [sent, stored]] of cases.entries()) {
208	    const over = { title: sent, ...hourSlot(i) };
209	    const res = await post(port, body(over));
210	    assert.equal(res.status, 201, `title #${i} status`);
211	    assert.deepEqual(res.json, { id: i + 1, ...valid(over), title: stored }, `title #${i} body`);
212	    expected.push(res.json);
213	  }
214	  const list = await request(port, 'GET', '/api/bookings');
215	  assert.deepEqual(list.json.bookings, expected, 'GET returns trimmed titles');
216	});
217	
218	// ---------- rule 6 ----------
219	
